private void pop(final String descriptor){
    // This method pops the abstract types represented in the descriptor
    // from the output frame stack.
    int pos = 0;
    if (descriptor.charAt(0) == '(') {
        // Method descriptor – pop argument types only
        pos = 1;
        while (descriptor.charAt(pos) != ')') {
            // Skip array brackets
            while (descriptor.charAt(pos) == '[') {
                pos++;
            }
            char c = descriptor.charAt(pos);
            if (c == 'L') {
                // Object type: consume until ';'
                pos = descriptor.indexOf(';', pos);
            }
            // Move past the type character or ';'
            pos++;
            // Pop one type entry from the stack
            outputFrameStack.pop();   // assume the stack exists and is of a suitable type
        }
    } else {
        // Single type descriptor – pop it
        while (pos < descriptor.length()) {
            // Skip array brackets
            while (descriptor.charAt(pos) == '[') {
                pos++;
            }
            char c = descriptor.charAt(pos);
            if (c == 'L') {
