private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }
    if (node.prev != null) {
        node.prev.next = node.next;
    } else {
        head = node.next;
    }
    if (node.next != null) {
        node.next.prev = node.prev;
    } else {
        tail = node.prev;
    }
    node.prev = null;
    node.next = null;
    size--;
    return true;
}

