    java.util.List<V> left = new java.util.ArrayList<>();
    java.util.List<V> right = new java.util.ArrayList<>();
    for (java.util.Map.Entry<String,V> entry : resultMap.entrySet()){
        String key = entry.getKey();
        V vertex = entry.getValue();
        target.addVertex(vertex);
        if (key.startsWith("left")){
            left.add(vertex);
        } else if (key.startsWith("right")){
            right.add(vertex);
        }
    }
    for (V u : left){
        for (V v : right){
            target.addEdge(u, v);
        }
    }
}

@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap) {
    // Clear existing graph data
    target.removeAllEdges(new java.util.HashSet<E>(target.edgeSet()));
    target.removeAllVertices(new java.util.HashSet<V>(target.vertexSet()));
    // Partition vertices into two sets
    java.util.List<V> left = new java.util.ArrayList<>();
    java.util.List<V> right = new java.util.ArrayList<>();
    for (java.util.Map.Entry<String,V> entry : resultMap.entrySet()) {
        if (entry.getKey().hashCode() % 2 == 0) {
            left.add(entry.getValue());
        } else {
            right.add(entry.getValue());
        }
    }
    // Add all vertices to the graph
    for (V v : left) target.addVertex(v);
    for (V v : right) target.addVertex(v);
    // Add edges to form a complete bipartite graph
    for (V u : left) {
        for (V v : right) {
            target.addEdge(u, v);
        }
    }
}

