    if (tour == null || tour.isEmpty()){
        return null;
    }
    List<E> edgeList = new ArrayList<>(tour);
    List<V> vertexList = new ArrayList<>();
    if (!edgeList.isEmpty()){
        E first = edgeList.get(0);
        V source = graph.getEdgeSource(first);
        V target = graph.getEdgeTarget(first);
        vertexList.add(source);
        vertexList.add(target);
        for (int i = 1; i < edgeList.size(); i++){
            E e = edgeList.get(i);
            V s = graph.getEdgeSource(e);
            V t = graph.getEdgeTarget(e);
            V last = vertexList.get(vertexList.size()-1);
            if (s.equals(last)){
                vertexList.add(t);
            } else if (t.equals(last)){
                vertexList.add(s);
            } // else ignore mismatched edge
        }
    }
    return new org.jgrapht.graph.GraphPathImpl<>(graph, vertexList, edgeList);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    if (tour == null || graph == null || tour.isEmpty()) {
        return null;
    }
    Set<E> remaining = new HashSet<>(tour);
    Iterator<E> it = remaining.iterator();
    E first = it.next();
    remaining.remove(first);
    V start = graph.getEdgeSource(first);
    V current = graph.getEdgeTarget(first);
    List<E> edgeOrder = new ArrayList<>();
    edgeOrder.add(first);
    while (!remaining.isEmpty()) {
        boolean found = false;
        Iterator<E> iter = remaining.iterator();
        while (iter.hasNext()) {
            E e = iter.next();
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(current)) {
                current = tgt;
                edgeOrder.add(e);
                iter.remove();
                found = true;
                break;
            } else if (tgt.equals(current)) {
                current = src;
                edgeOrder.add(e);
                iter.remove();
                found = true;
                break;
            }
        }
        if (!found) {
            return null; // cannot form a continuous tour with the given edges
        }
    }
    double totalWeight = 0.0;
    for (E e : edgeOrder) {
        totalWeight += graph.getEdgeWeight(e);
    }
