    // edge, but this method will still construct a path even if they differ.
    V startVertex = graph.getEdgeSource(edgeList.get(0));
    V endVertex = graph.getEdgeTarget(edgeList.get(edgeList.size() - 1));
    // The total weight of the path is set to 0 as a placeholder; callers that care can
    // compute the weight separately or use a custom implementation.
    return new org.jgrapht.graph.DefaultGraphPath<>(graph, startVertex, endVertex, edgeList, 0);
