protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || tour.isEmpty()){
        return new GraphWalk<>(graph, new ArrayList<>(), new ArrayList<>(), 0);
    }
    // copy edges to a mutable list
    List<E> edges = new ArrayList<>(tour);
    // keep track of visited edges
    Set<E> visited = new HashSet<>();
    List<E> orderedEdges = new ArrayList<>();
    List<V> vertices = new ArrayList<>();
    // start at the source of the first edge
    E first = edges.get(0);
    V current = graph.getEdgeSource(first);
    vertices.add(current);
    visited.add(first);
    orderedEdges.add(first);
    boolean forward = true; // direction flag
    // determine the next vertex
    V next = graph.getEdgeTarget(first);
    vertices.add(next);
    if (!forward) {
        // if we start by going backwards, swap
        V temp = current;
        current = next;
        next = temp;
    }
    // continue traversing until all edges are visited
    while (visited.size() < edges.size()){
        boolean found = false;
        for (E e : edges){
            if (visited.contains(e)) continue;
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(current)){
                orderedEdges.add(e);
                visited.add(e);
                current = tgt;
                vertices.add(current);
                found = true;
                break;
            } else if (tgt.equals(current)){
                orderedEdges.add(e);
                visited.add(e);
                current = src;
                vertices.add(current);
                found = true;
                break;
            }
        }
        if (!found){
            // cannot continue, break out
            break;
        }
    }
    // compute total weight
    double weight = 0.0;
    for (E e : orderedEdges){
        weight += graph.getEdgeWeight(e);
    }
    return new GraphWalk<>(graph, vertices, orderedEdges, weight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    if(tour==null || tour.isEmpty()){
        return null;
    }

    // Ordered list of edges to form a path
    List<E> edgeList = new ArrayList<>(tour.size());
    // Ordered list of vertices
    List<V> vertexList = new ArrayList<>(tour.size() + 1);

    // Use a copy of the set to modify
    Set<E> remaining = new HashSet<>(tour);

    // Start with an arbitrary edge
    E firstEdge = remaining.iterator().next();
    remaining.remove(firstEdge);
    edgeList.add(firstEdge);
    V current = graph.getEdgeSource(firstEdge);
    V next = graph.getEdgeTarget(firstEdge);
    vertexList.add(current);
    vertexList.add(next);
    double totalWeight = graph.getEdgeWeight(firstEdge);

    // Build the rest of the path
    while(!remaining.isEmpty()){
        boolean found = false;
        Iterator<E> it = remaining.iterator();
        while(it.hasNext()){
            E e = it.next();
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if(src.equals(next)){
                // Forward direction
                edgeList.add(e);
                next = tgt;
                vertexList.add(tgt);
                totalWeight += graph.getEdgeWeight(e);
                it.remove();
                found = true;
                break;
            }else if(tgt.equals(next)){
                // Backward direction (undirected graph)
                edgeList.add(e);
                next = src;
                vertexList.add(src);
                totalWeight += graph.getEdgeWeight(e);
                it.remove();
                found = true;
                break;
            }
        }
        if(!found){
            // No connecting edge found: the set does not represent a valid path
            return null;
        }
    }

    // Define an anonymous GraphPath implementation
    return new GraphPath<V,E>() {
        @Override public Graph<V,E> getGraph() { return graph; }
        @Override public V getStartVertex() { return vertexList.get(0); }
        @Override public V getEndVertex() { return vertexList.get(vertexList.size()-1); }
        @Override public List<V> getVertexList() { return vertexList; }
        @Override public List<E> getEdgeList() { return edgeList; }
        @Override public double getWeight() { return totalWeight; }
    };
