public static List<PathSegmentImpl> decodePath(URI u,boolean decode){
    java.util.List<PathSegmentImpl> result = new java.util.ArrayList<>();
    String path = u.getRawPath();
    if(path == null || path.isEmpty()){
        return result;
    }
    if(path.startsWith("/")){
        path = path.substring(1);
    }
    String[] parts = path.split("/");
    for(String part : parts){
        if(part.isEmpty()){
            continue;
        }
        String val = part;
        if(decode){
            try{
                val = java.net.URLDecoder.decode(part, "UTF-8");
            } catch(java.io.UnsupportedEncodingException e){
                throw new RuntimeException(e);
            }
        }
        result.add(new PathSegmentImpl(val));
    }
    return result;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    String path = u.getPath();
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    int start = 0;
    if (path.charAt(0) == '/') {
        start = 1;
    }
    String remaining = path.substring(start);
    if (remaining.isEmpty()) {
        return segments;
    }
    String[] parts = remaining.split("/", -1);
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        String value = part;
        if (decode) {
            try {
