public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (nameStart <= 0 || nameStart >= buf.length()) {
        return;
    }
    // Build abbreviated form for the part of the name starting at nameStart
    String original = buf.toString();
    StringBuilder abbr = new StringBuilder();
    String[] tokens = original.substring(nameStart).split("\\.");
    for (String token : tokens) {
        if (!token.isEmpty()) {
            abbr.append(token.charAt(0)).append('.');
        }
    }
    if (abbr.length() > 0) {
        abbr.setLength(abbr.length() - 1); // remove trailing dot
    }
    buf.setLength(0);
    buf.append(original, 0, nameStart).append(abbr);
}

