    int newPosition = this.pos + byteLength;
    if (newPosition > this.data.length) {
        // Grow to at least the required size, typically doubling for amortized performance
        int newCapacity = Math.max(this.data.length * 2, newPosition);
        this.data = java.util.Arrays.copyOf(this.data, newCapacity);
