        return 2;
    }
    int candidate = desiredCapacity;
    while (true) {
        if (candidate <= 1) {
            candidate = 2;
        } else {
            boolean isPrime = true;
            for (int i = 2; i * i <= candidate; i++) {
                if (candidate % i == 0) {
                    isPrime = false;
                    break;
                }
            }
            if (isPrime) {
                return candidate;
            }
        }
        candidate++;
        if (desiredCapacity >= 1000) {
            int limit = (int) Math.ceil(desiredCapacity * 1.11);
            if (candidate > limit) {
                return desiredCapacity;
            }
        }
    }
}

