public final byte[] toByteArray(){
    // Combine all buffer contents into a single byte array
    int totalSize = 0;
    for (ByteBuffer buf : buffers) {
        totalSize += buf.remaining();
    }
    byte[] result = new byte[totalSize];
    int offset = 0;
    for (ByteBuffer buf : buffers) {
        ByteBuffer dup = buf.duplicate();
        int len = dup.remaining();
        dup.get(result, offset, len);
        offset += len;
    }
    return result;
}

public final byte[] toByteArray() {
    if (buffer == null) {
        return new byte[0];
    }
    int size = buffer.remaining();
    byte[] result = new byte[size];
    buffer.get(result);
    return result;
}

public final byte[] toByteArray() {
    /* If a single ByteBuffer holds the data, return its content as a new byte array. */
    if (buffer == null) {
        return new byte[0];
    }
    if (buffer.hasArray()) { // Direct backing array
        int pos   = buffer.position();
        int limit = buffer.limit();
        return java.util.Arrays.copyOfRange(buffer.array(), pos, limit);
    } else { // No backing array; copy manually
        byte[] bytes = new byte[buffer.remaining()];
        buffer.get(bytes);
        return bytes;
    }
}

